add_filter( 'the_content', 'perfectpixel_reading_time', 5 );

function perfectpixel_reading_time( $content ) {
	if ( ! is_singular( 'post' ) || ! in_the_loop() || ! is_main_query() ) {
		return $content;
	}
	// str_word_count() ignores Greek letters, so count Unicode words instead.
	$words   = preg_match_all( '/[\p{L}\p{N}][\p{L}\p{N}\p{Mn}\'’-]*/u', wp_strip_all_tags( strip_shortcodes( $content ) ) );
	$minutes = max( 1, (int) ceil( $words / max( 50, (int) '{{reading_time_wpm}}' ) ) );
	$unit    = 1 === $minutes ? '{{reading_time_minute}}' : '{{reading_time_minutes}}';
	return '<p class="perfectpixel-reading-time">' . esc_html( '{{reading_time_label}}' . ' ' . $minutes . ' ' . $unit ) . '</p>' . $content;
}
